using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using Microsoft.CodeAnalysis.CSharp.Syntax;
static class Program
{
 static string Type(ITypeSymbol s){if(s is IArrayTypeSymbol a){if(a.Rank!=1)throw new InvalidDataException("Nonvector source array");return Type(a.ElementType)+"[]";}if(s is IPointerTypeSymbol p)return Type(p.PointedAtType)+"*";if(s is ITypeParameterSymbol g)return "!"+g.Ordinal;if(s is not INamedTypeSymbol n||s.TypeKind==TypeKind.Error)throw new InvalidDataException("Unbound source type:"+s);var own=n.ContainingType!=null?Type(n.ContainingType)+"/":n.ContainingNamespace.IsGlobalNamespace?"":n.ContainingNamespace.ToDisplayString()+".";var name=n.MetadataName;if(n.IsGenericType)name+="<"+string.Join(",",n.TypeArguments.Select(Type))+">";return own+name;}
 static string Owner(INamedTypeSymbol n){return (n.ContainingType!=null?Owner(n.ContainingType)+"/":n.ContainingNamespace.IsGlobalNamespace?"":n.ContainingNamespace.ToDisplayString()+".")+n.MetadataName;}
 static object Value(TypedConstant c){if(c.Kind==TypedConstantKind.Array)return new{kind="array",values=c.Values.Select(Value)};if(c.Kind==TypedConstantKind.Type)return new{kind="type",type=Type((ITypeSymbol)c.Value)};return new{kind=c.Kind.ToString(),type=c.Type==null?null:Type(c.Type),value=c.Value};}
 static object[] Attrs(IEnumerable<AttributeData> a)=>a.Where(x=>x.AttributeClass?.ToDisplayString()=="System.Runtime.InteropServices.MarshalAsAttribute").Select(x=>(object)new{constructor_type=x.AttributeClass.ToDisplayString(),constructor_arguments=x.ConstructorArguments.Select(Value),named_arguments=x.NamedArguments.Select(z=>new{name=z.Key,value=Value(z.Value)}),source_text=x.ApplicationSyntaxReference?.GetSyntax().ToString()}).ToArray();
 static int Main(string[] a){var source=Path.GetFullPath(a[0]);var parse=new CSharpParseOptions(LanguageVersion.CSharp8,preprocessorSymbols:new[]{"STEAMWORKS_WIN","STEAMWORKS_X64"});var trees=Directory.GetFiles(source,"*.cs",SearchOption.AllDirectories).Select(p=>CSharpSyntaxTree.ParseText(File.ReadAllText(p),parse,p)).ToArray();var refs=new[]{a[1]}.Concat(a.Skip(3)).Select(p=>MetadataReference.CreateFromFile(p));var c=CSharpCompilation.Create("OfficialSteamworks14Source",trees,refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary,allowUnsafe:true));var fields=new List<object>();var methods=new List<object>();
 foreach(var tree in trees){var model=c.GetSemanticModel(tree);foreach(var node in tree.GetRoot().DescendantNodes().OfType<FieldDeclarationSyntax>()){foreach(var variable in node.Declaration.Variables){var f=(IFieldSymbol)model.GetDeclaredSymbol(variable);var attrs=Attrs(f.GetAttributes());if(attrs.Length==0)continue;fields.Add(new{owner=Owner(f.ContainingType),name=f.Name,type=Type(f.Type),is_static=f.IsStatic,is_readonly=f.IsReadOnly,marshal=attrs,path=tree.FilePath,line=tree.GetLineSpan(node.Span).StartLinePosition.Line+1,source_declaration=node.ToString()});}}
 foreach(var node in tree.GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>()){var m=(IMethodSymbol)model.GetDeclaredSymbol(node);if(Owner(m.ContainingType)!="Steamworks.NativeMethods")continue;var pars=m.Parameters.Select(p=>new{sequence=p.Ordinal+1,name=p.Name,type=Type(p.Type)+(p.RefKind==RefKind.None?"":"&"),ref_kind=p.RefKind.ToString(),marshal=Attrs(p.GetAttributes())}).ToArray();methods.Add(new{owner=Owner(m.ContainingType),name=m.Name,@return=Type(m.ReturnType),parameters=pars,return_marshal=Attrs(m.GetReturnTypeAttributes()),path=tree.FilePath,line=tree.GetLineSpan(node.Span).StartLinePosition.Line+1});}}
 File.WriteAllText(a[2],JsonSerializer.Serialize(new{schema="official-steamworks14-semantic-marshalling/v1",profile="STEAMWORKS_WIN;STEAMWORKS_X64",source_files=trees.Length,fields,methods,semantic_errors=c.GetDiagnostics().Where(d=>d.Severity==DiagnosticSeverity.Error).Take(30).Select(d=>d.ToString())},new JsonSerializerOptions{WriteIndented=true}));return 0;}
}
